const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STICKERS={'Arcade Originals':'🦊 🤖 🐲 🦄 🐸 🦉 🐙 🍕 🍔 🧁 🍩 🐞 🎈 ⭐ 🏰 🚀',Animals:'🐱 🐶 🦊 🐻 🐼 🦁 🐯 🐸 🐵 🐨 🦋 🐝 🐙 🐬 🐳 🦉 🦜 🐧 🦔 🦩',Dinosaurs:'🦖 🦕 🥚 🦴 🐲 🐾 🌋 🌴 🪨 🪺',Vehicles:'🚗 🚕 🚌 🏎️ 🚓 🚑 🚒 🚜 🚲 🛴 🚂 🚁 ✈️ 🚀 🛸 ⛵ 🚢',Space:'🪐 🌎 🌙 ☀️ ⭐ 🌟 💫 ☄️ 🚀 🛸 👽 🧑‍🚀 🔭 🌌',Sports:'⚽ 🏀 🏈 ⚾ 🎾 🏐 🏉 🎱 🏓 🏸 🥊 🛹 🏆 🥇',Food:'🍎 🍓 🍉 🍊 🍇 🍍 🍌 🍕 🍔 🌮 🍟 🍦 🧁 🍩 🍪 🥕 🥑 🍿',Flowers:'🌸 🌼 🌻 🌺 🌷 🪷 🌹 🥀 💐 🍀 🌿 🌵 🍄 🌲',Hearts:'❤️ 🧡 💛 💚 💙 💜 🩷 🤍 🖤 💖 💘 💝 💕 💓',Stars:'⭐ 🌟 ✨ 💫 ✦ ✧ ★ ☆ ✴️ 🔆 ❇️ 🌠',Emojis:'😀 😎 🥰 🤩 😂 😜 🥳 😇 🤗 😴 😱 🤠 🤖 👻 💩 👾',Fantasy:'🦄 🐲 🧚 🧙 🧜 🧝 🧞 🦸 🦹 🏰 🔮 🪄 🗡️ 🛡️',Seasonal:'🎃 👻 🕸️ 🍂 🍁 🎄 🎅 🎁 ⛄ ❄️ 🌷 🐰 🥚 🏖️ ☀️ 🎆',Symbols:'🔵 🟣 🟡 🔴 🟢 🟠 🔷 🔶 🔺 🔻 💎 🔥 ⚡ 🌈 🎵 🎶 ☮️ ☯️ ♾️'};
const TOOLS=[['pencil','✎','Pencil'],['marker','▰','Marker'],['brush','🖌','Brush'],['spray','⁙','Spray'],['eraser','▱','Eraser'],['fill','◕','Fill'],['line','╱','Line'],['circle','◯','Circle'],['rect','□','Rectangle'],['triangle','△','Triangle'],['star','☆','Star'],['select','↖','Move']];
const SWATCHES=['#21213b','#ffffff','#6e4bc5','#aa77ff','#d69cff','#ee68a4','#ff8dab','#ff4c64','#ed774e','#ffab4e','#ffd75f','#fff0a9','#8dc74c','#c4ed79','#29aa7d','#4cddbb','#36c5d5','#83ecf5','#398ddd','#87b5ff','#713e87','#a97254','#c89a74','#eeccae','#aaaac5','#66677f','#353b62','#161d34'];
export function openStudio(host,{exit,notify,ask,modal}){
const W=1440,H=900;let disposed=false,raf,tool='brush',color='#a47bff',color2='#ff7bab',size=18,settings=newDrawingSettings(),background='paper',pointers=new Map(),objects=[],selected=null,images=new Map(),history=[],future=[],drawingId=null,artQualified=false,owner=DB.active,name='My masterpiece',category='Arcade Originals',collab=false,p2=DB.profiles.find(p=>p.id!==DB.active)?.id||null,dirty=false,base=document.createElement('canvas');base.width=W;base.height=H;let bc=base.getContext('2d',{willReadFrequently:true});
host.innerHTML=`<div class="studio-room"><header class="creative-header"><button class="btn secondary" id="studioExit">⌂ LOBBY</button><div><span class="eyebrow">IMAGINATION IS THE ONLY RULE</span><h1>CREATIVE <em>STUDIO</em></h1></div><div class="creative-actions"><button class="btn secondary" id="studioGallery">▦ GALLERY</button><button class="btn primary" id="studioSave">SAVE ART ✦</button><button class="btn accent" id="studioExport">EXPORT ↓</button></div></header><div class="studio-modebar"><span id="studioOwner">${player().avatar} ${esc(player().name)}’s canvas</span><label class="check-label"><input type="checkbox" id="collab">Create together</label><select id="studioP2" aria-label="Collaborating player" hidden>${DB.profiles.filter(p=>p.id!==DB.active).map(p=>`<option value="${p.id}">${p.avatar} ${esc(p.name)}</option>`).join('')}</select><label>Paper<select id="paper"><option value="paper">White paper</option><option value="cream">Warm cream</option><option value="dots">Dot grid</option><option value="blueprint">Blueprint</option><option value="space">Midnight</option></select></label><span id="studioStatus">A fresh canvas. A million possibilities.</span></div><div class="studio-workspace"><aside class="tool-rail">${TOOLS.map(([id,icon,label])=>`<button class="tool-btn ${id===tool?'selected':''}" data-tool="${id}" title="${label}"><b>${icon}</b><span>${label}</span></button>`).join('')}</aside><div class="art-stage" id="artStage"><div class="canvas-shadow"><canvas id="artCanvas" width="1440" height="900" aria-label="Artwork canvas"></canvas></div><div class="collab-label" id="collabLabel" hidden>LEFT START = PLAYER 1 COLOR · RIGHT START = PLAYER 2 COLOR</div></div><aside class="studio-inspector"><div class="inspector-heading">YOUR TOOLBOX <span>✦</span></div><button class="btn secondary full" id="stickers">✿ STICKER HUB</button><label class="btn secondary full file-btn">▧ ADD PHOTO<input id="imageUpload" type="file" accept="image/jpeg,image/png" hidden></label><p class="tiny muted">JPG or PNG. Photos stay on this device.</p><div class="brush-preview"><span id="brushDot"></span></div><label class="slider-label">Brush size <output id="sizeValue">18 px</output><input id="brushSize" type="range" min="1" max="100" value="18"></label><label class="check-label"><input id="shapeFill" type="checkbox">Fill shapes</label><div class="object-panel" id="objectPanel" hidden><h3>Selected layer</h3><label class="slider-label">Size <output id="objectSizeValue"></output><input id="objectSize" type="range" min="24" max="800" value="160"></label><label class="slider-label">Rotation <output id="rotationValue"></output><input id="objectRotate" type="range" min="-180" max="180" value="0"></label><div class="object-buttons"><button class="btn secondary" id="layerUp">↑ FRONT</button><button class="btn secondary" id="layerDown">↓ BACK</button><button class="btn secondary" id="cropImage">▧ CROP SQUARE</button><button class="btn danger" id="deleteObject">DELETE</button></div></div><p class="tiny muted">Move stickers and photos with the Move tool. Use two fingers on one layer to resize and rotate it.</p></aside></div><footer class="studio-tools"><div class="history-buttons"><button class="icon-btn" id="undo" aria-label="Undo">↶</button><button class="icon-btn" id="redo" aria-label="Redo">↷</button><button class="icon-btn" id="clearArt" aria-label="Clear canvas">♧</button></div><div class="swatch-tray">${SWATCHES.map(c=>`<button class="color-swatch ${c===color?'selected':''}" data-swatch="${c}" style="--swatch:${c}" aria-label="Color ${c}"></button>`).join('')}</div><label class="custom-color" title="Custom color"><input id="customColor" type="color" value="${color}" aria-label="Custom drawing color">＋</label><label class="p2-color" id="p2ColorLabel" hidden>P2<input id="p2Color" type="color" value="${color2}" aria-label="Player two color"></label><button class="icon-btn" id="studioFull" aria-label="Fullscreen">⛶</button></footer><div class="sticker-drawer" id="stickerDrawer" hidden><div><span class="eyebrow">A WORLD OF LITTLE EXTRAS</span><h2>Sticker Hub</h2><button class="icon-btn" id="closeStickers" aria-label="Close sticker hub">✕</button></div><nav id="stickerTabs"></nav><div class="sticker-grid" id="stickerGrid"></div><p>Tap to add, or drag a sticker onto your canvas.</p></div></div>`;

const workspace=host.querySelector('.studio-workspace'),leftRail=host.querySelector('.tool-rail'),shared=host.querySelector('.studio-inspector');leftRail.className='player-toolbox player-one';leftRail.id='playerOneTools';leftRail.setAttribute('aria-label','Player 1 drawing controls');
const rightRail=document.createElement('aside');rightRail.id='playerTwoTools';rightRail.className='player-toolbox player-two';rightRail.setAttribute('aria-label','Player 2 drawing controls');rightRail.hidden=true;workspace.append(rightRail);
shared.classList.add('shared-art-tools');shared.hidden=true;workspace.after(shared);
for(const selector of['.brush-preview','#brushSize','#shapeFill']){let el=shared.querySelector(selector);if(el)selector==='.brush-preview'?el.remove():el.closest('label').remove();}
const extras=document.createElement('div');extras.className='shared-art-buttons';const toggle=document.createElement('button');toggle.className='btn secondary';toggle.textContent='▧ LAYERS';toggle.id='artLayers';toggle.setAttribute('aria-expanded','false');extras.append(host.querySelector('#stickers'),host.querySelector('#imageUpload').closest('label'),toggle);host.querySelector('.studio-modebar').append(extras);toggle.onclick=()=>{shared.hidden=!shared.hidden;toggle.setAttribute('aria-expanded',String(!shared.hidden));};
for(const selector of['.swatch-tray','.custom-color','.p2-color'])host.querySelector(selector)?.remove();
const footerHint=document.createElement('span');footerHint.className='studio-help';footerHint.textContent='Choose your tools at the side. Make something wonderful.';host.querySelector('.studio-tools').append(footerHint);
host.querySelector('#studioSave').textContent='SAVE PROJECT ✦';

const $=s=>host.querySelector(s),canvas=$('#artCanvas'),ctx=canvas.getContext('2d'),status=t=>{$('#studioStatus').textContent=t;};
function snapshot(){return{raster:base.toDataURL('image/png'),objects:structuredClone(objects),background};}
function checkpoint(){if(pointers.size)return;history.push(snapshot());if(history.length>24)history.shift();future=[];dirty=true;updateHistory();}
async function loadImage(src){if(images.has(src))return images.get(src);let img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('The image could not be opened.'));img.src=src;});images.set(src,img);return img;}
async function applySnapshot(s){let img=await loadImage(s.raster);bc.clearRect(0,0,W,H);bc.drawImage(img,0,0,W,H);await Promise.all(s.objects.filter(o=>o.kind==='image').map(o=>loadImage(o.src)));objects=structuredClone(s.objects);background=s.background;$('#paper').value=background;selected=null;inspector();dirty=true;updateHistory();}
function updateHistory(){$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;}
$('#undo').onclick=async()=>{if(!history.length||pointers.size)return;future.push(snapshot());await applySnapshot(history.pop());};$('#redo').onclick=async()=>{if(!future.length||pointers.size)return;history.push(snapshot());await applySnapshot(future.pop());};
function toolbar(side){const rail=side?rightRail:leftRail,p=settings[side],profile=player(side?p2:owner)||player();rail.style.setProperty('--artist',profile.color);rail.innerHTML=`<div class="artist-heading"><span class="avatar">${profile.avatar}</span><div><small>PLAYER ${side+1}</small><strong>${esc(profile.name)}</strong></div></div><div class="artist-tools">${TOOLS.map(([id,icon,label])=>`<button class="tool-btn ${id===p.tool?'selected':''}" data-artist-tool="${id}" aria-label="Player ${side+1} ${label}" aria-pressed="${id===p.tool}"><b>${icon}</b><span>${label}</span></button>`).join('')}</div><label class="artist-size">Brush size <output>${p.size} px</output><input type="range" data-artist-size min="1" max="100" value="${p.size}" aria-label="Player ${side+1} brush size"></label><label class="check-label"><input type="checkbox" data-artist-fill ${p.fill?'checked':''}>Fill shapes</label><div class="artist-palette">${SWATCHES.map(c=>`<button class="color-swatch ${c===p.color?'selected':''}" data-artist-color="${c}" style="--swatch:${c}" aria-label="Player ${side+1} color ${c}" aria-pressed="${c===p.color}"></button>`).join('')}</div><label class="artist-custom">Custom color<input data-artist-custom type="color" value="${p.color}" aria-label="Player ${side+1} custom color"></label>`;
rail.querySelectorAll('[data-artist-tool]').forEach(el=>el.onclick=()=>{settings[side].tool=el.dataset.artistTool;rail.querySelectorAll('[data-artist-tool]').forEach(b=>{b.classList.toggle('selected',b===el);b.setAttribute('aria-pressed',String(b===el));});status(profile.name+' · '+el.textContent.trim()+' ready.');});
rail.querySelector('[data-artist-size]').oninput=e=>{settings[side].size=+e.target.value;rail.querySelector('output').textContent=e.target.value+' px';};rail.querySelector('[data-artist-fill]').onchange=e=>settings[side].fill=e.target.checked;
function chooseColor(c){settings[side].color=c;rail.querySelector('[data-artist-custom]').value=c;rail.querySelectorAll('[data-artist-color]').forEach(el=>{el.classList.toggle('selected',el.dataset.artistColor===c);el.setAttribute('aria-pressed',String(el.dataset.artistColor===c));});}
rail.querySelectorAll('[data-artist-color]').forEach(el=>el.onclick=()=>chooseColor(el.dataset.artistColor));rail.querySelector('[data-artist-custom]').oninput=e=>chooseColor(e.target.value);
}
function toolbars(){if(!p2||p2===owner||!player(p2))p2=DB.profiles.find(p=>p.id!==owner)?.id||null;if(!p2)collab=false;$('#studioP2').innerHTML=DB.profiles.filter(p=>p.id!==owner).map(p=>`<option value="${p.id}" ${p.id===p2?'selected':''}>${p.avatar} ${esc(p.name)}</option>`).join('');$('#studioP2').hidden=!collab;$('#collab').checked=collab;toolbar(0);toolbar(1);rightRail.hidden=!collab;workspace.classList.toggle('collaborating',collab);$('#collabLabel').hidden=!collab;$('#collabLabel').textContent='START LEFT: '+(player(owner)?.name||'Player 1')+' · START RIGHT: '+(player(p2)?.name||'Player 2')+' · KEEP DRAWING ANYWHERE';}
function chooseTool(id,side=0){settings[side].tool=id;toolbar(side);canvas.style.cursor=id==='select'?'grab':'crosshair';}
$('#paper').onchange=e=>{checkpoint();background=e.target.value;};
$('#clearArt').onclick=async()=>{if(await ask('A fresh canvas?','This clears your current canvas. You can undo it, and saved gallery artwork is kept.')){checkpoint();bc.clearRect(0,0,W,H);objects=[];selected=null;inspector();status('Fresh start. What will you make?');}};
$('#studioExit').onclick=async()=>{if(dirty&&!await ask('Leave the studio?','You have unsaved edits. Save your artwork first to keep it in the gallery.'))return;exit();};$('#studioFull').onclick=()=>document.querySelector('#fullscreen').click();
$('#collab').onchange=e=>{if(e.target.checked&&!p2){e.target.checked=false;notify('Create a second player profile to collaborate.');return;}collab=e.target.checked;$('#studioP2').hidden=!collab;$('#collabLabel').hidden=!collab;toolbars();status(collab?'Start on your side to use your own tool, color, and brush size. Both can draw anywhere.':'Solo studio. Your imagination takes the lead.');};$('#studioP2').onchange=e=>{p2=e.target.value;toolbars();};
function point(e){let r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H};}
function objectAt(p){return [...objects].reverse().find(o=>{let a=-o.rotation*Math.PI/180,x=(p.x-o.x)*Math.cos(a)-(p.y-o.y)*Math.sin(a),y=(p.x-o.x)*Math.sin(a)+(p.y-o.y)*Math.cos(a);return Math.abs(x)<=o.w/2&&Math.abs(y)<=o.h/2;});}
function inspector(){let o=objects.find(o=>o.id===selected);$('#objectPanel').hidden=!o;if(o){shared.hidden=false;$('#artLayers').setAttribute('aria-expanded','true');$('#objectSize').value=o.w;$('#objectSizeValue').textContent=Math.round(o.w)+' px';$('#objectRotate').value=o.rotation;$('#rotationValue').textContent=Math.round(o.rotation)+'°';$('#cropImage').hidden=o.kind!=='image';}}
$('#objectSize').onpointerdown=()=>checkpoint();$('#objectSize').oninput=e=>{let o=objects.find(o=>o.id===selected);if(o){let ratio=o.h/o.w;o.w=+e.target.value;o.h=o.w*ratio;dirty=true;inspector();}};$('#objectRotate').onpointerdown=()=>checkpoint();$('#objectRotate').oninput=e=>{let o=objects.find(o=>o.id===selected);if(o){o.rotation=+e.target.value;dirty=true;inspector();}};
$('#layerUp').onclick=()=>{let i=objects.findIndex(o=>o.id===selected);if(i>=0){checkpoint();objects.push(objects.splice(i,1)[0]);}};$('#layerDown').onclick=()=>{let i=objects.findIndex(o=>o.id===selected);if(i>=0){checkpoint();objects.unshift(objects.splice(i,1)[0]);}};$('#deleteObject').onclick=()=>{checkpoint();objects=objects.filter(o=>o.id!==selected);selected=null;inspector();};
$('#cropImage').onclick=async()=>{let o=objects.find(o=>o.id===selected);if(!o||o.kind!=='image')return;checkpoint();let im=await loadImage(o.src),side=Math.min(im.naturalWidth,im.naturalHeight),c=document.createElement('canvas');c.width=c.height=Math.min(side,1600);c.getContext('2d').drawImage(im,(im.naturalWidth-side)/2,(im.naturalHeight-side)/2,side,side,0,0,c.width,c.height);o.src=c.toDataURL('image/png');await loadImage(o.src);o.h=o.w;inspector();};
function stroke(c,p,prev){let t=c.getContext?c.getContext('2d'):c;c.save();c.globalCompositeOperation=p.tool==='eraser'?'destination-out':'source-over';c.strokeStyle=p.color;c.fillStyle=p.color;c.lineCap='round';c.lineJoin='round';c.lineWidth=p.size;if(p.tool==='pencil')c.lineWidth=Math.max(1,p.size*.3);if(p.tool==='marker')c.globalAlpha=.4;if(p.tool==='brush'){c.shadowColor=p.color;c.shadowBlur=p.size*.18;c.globalAlpha=.8;}if(p.tool==='spray'){let distance=Math.hypot(p.x-prev.x,p.y-prev.y),steps=Math.max(1,Math.ceil(distance/8));for(let k=0;k<=steps;k++){let x=prev.x+(p.x-prev.x)*k/steps,y=prev.y+(p.y-prev.y)*k/steps;for(let i=0;i<Math.max(15,p.size*2);i++){let a=Math.random()*Math.PI*2,r=Math.sqrt(Math.random())*p.size;c.globalAlpha=.25+Math.random()*.6;c.fillRect(x+Math.cos(a)*r,y+Math.sin(a)*r,1.5,1.5);}}}else{c.beginPath();c.moveTo(prev.x,prev.y);c.lineTo(p.x+.01,p.y+.01);c.stroke();}c.restore();}
function shape(c,p){let x=p.start.x,y=p.start.y,dx=p.x-x,dy=p.y-y;c.save();c.lineWidth=p.size;c.lineCap='round';c.strokeStyle=p.color;c.fillStyle=p.color;c.beginPath();if(p.tool==='line'){c.moveTo(x,y);c.lineTo(p.x,p.y);}if(p.tool==='rect')c.rect(Math.min(x,p.x),Math.min(y,p.y),Math.abs(dx),Math.abs(dy));if(p.tool==='circle')c.ellipse(x+dx/2,y+dy/2,Math.abs(dx/2),Math.abs(dy/2),0,0,Math.PI*2);if(p.tool==='triangle'){c.moveTo(x+dx/2,y);c.lineTo(p.x,p.y);c.lineTo(x,p.y);c.closePath();}if(p.tool==='star'){let r=Math.hypot(dx,dy);for(let i=0;i<10;i++){let a=i*Math.PI/5-Math.PI/2,q=i%2?r*.45:r;c.lineTo(x+Math.cos(a)*q,y+Math.sin(a)*q);}c.closePath();}if(p.fill&&p.tool!=='line')c.fill();else c.stroke();c.restore();}
function bucket(p){let data=bc.getImageData(0,0,W,H),a=data.data,x=Math.floor(p.x),y=Math.floor(p.y);if(x<0||y<0||x>=W||y>=H)return;let start=(y*W+x)*4,orig=Array.from(a.slice(start,start+4)),hex=p.color.replace('#',''),fill=[parseInt(hex.slice(0,2),16),parseInt(hex.slice(2,4),16),parseInt(hex.slice(4,6),16),255];if(orig.every((n,i)=>n===fill[i]))return;let stack=[y*W+x],seen=new Uint8Array(W*H),tolerance=35;while(stack.length){let pos=stack.pop();if(seen[pos])continue;seen[pos]=1;let i=pos*4;if(Math.abs(a[i]-orig[0])+Math.abs(a[i+1]-orig[1])+Math.abs(a[i+2]-orig[2])+Math.abs(a[i+3]-orig[3])>tolerance)continue;a.set(fill,i);let px=pos%W;if(px>0)stack.push(pos-1);if(px<W-1)stack.push(pos+1);if(pos>=W)stack.push(pos-W);if(pos<W*(H-1))stack.push(pos+W);}bc.putImageData(data,0,0);}
function down(e){e.preventDefault();if(disposed)return;let p=point(e);checkpoint();canvas.setPointerCapture(e.pointerId);const prefs=pointerDrawingSettings(settings,p.x,W,collab);let item={...p,start:{...p},...prefs};if(item.tool==='select'){let o=objectAt(p);selected=o?.id||null;if(o){item.object=o.id;item.offset={x:p.x-o.x,y:p.y-o.y};let otherEntry=[...pointers.entries()].find(([id,q])=>q.object===o.id);if(otherEntry){let [otherId,other]=otherEntry,first=e.pointerId<otherId?item:other,second=e.pointerId<otherId?other:item;item.gesture={firstId:Math.min(e.pointerId,otherId),distance:Math.hypot(second.x-first.x,second.y-first.y),angle:Math.atan2(second.y-first.y,second.x-first.x),w:o.w,h:o.h,rotation:o.rotation};other.gesture=item.gesture;}}inspector();}else if(item.tool==='fill'){bucket(item);dirty=true;return;}else if(!['line','circle','rect','triangle','star'].includes(item.tool))stroke(bc,item,p);pointers.set(e.pointerId,item);dirty=true;}
function move(e){let p=pointers.get(e.pointerId);if(!p)return;e.preventDefault();let q=point(e),prev={x:p.x,y:p.y};p.x=q.x;p.y=q.y;if(p.object){let o=objects.find(o=>o.id===p.object),other=[...pointers.entries()].find(([id,x])=>id!==e.pointerId&&x.object===p.object)?.[1];if(!o)return;if(other&&p.gesture){let first=p.gesture.firstId===e.pointerId?p:other,second=first===p?other:p,dist=Math.hypot(second.x-first.x,second.y-first.y),angle=Math.atan2(second.y-first.y,second.x-first.x);o.w=Math.max(24,p.gesture.w*dist/Math.max(1,p.gesture.distance));o.h=Math.max(24,p.gesture.h*dist/Math.max(1,p.gesture.distance));o.rotation=p.gesture.rotation+(angle-p.gesture.angle)*180/Math.PI;o.x=(p.x+other.x)/2;o.y=(p.y+other.y)/2;}else{o.x=clamp(p.x-p.offset.x,-o.w/3,W+o.w/3);o.y=clamp(p.y-p.offset.y,-o.h/3,H+o.h/3);}inspector();}else if(!['select','line','circle','rect','triangle','star'].includes(p.tool))stroke(bc,p,prev);}
function up(e){let p=pointers.get(e.pointerId);if(!p)return;if(e.type==='pointerup'&&['line','circle','rect','triangle','star'].includes(p.tool))shape(bc,p);pointers.delete(e.pointerId);for(let q of pointers.values())if(q.object===p.object){q.gesture=null;let o=objects.find(o=>o.id===q.object);if(o)q.offset={x:q.x-o.x,y:q.y-o.y};}status('Looking good. Your canvas, your rules.');}
canvas.addEventListener('pointerdown',down);canvas.addEventListener('pointermove',move);for(let ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,up);canvas.addEventListener('contextmenu',e=>e.preventDefault());
async function addSticker(text,x=W/2,y=H/2){if(category==='Arcade Originals'){const img=await loadImage(svgData(iconArt('sticker',text))),raster=document.createElement('canvas');raster.width=raster.height=256;raster.getContext('2d').drawImage(img,0,0,256,256);const src=raster.toDataURL('image/png');await loadImage(src);checkpoint();const o={id:uid(),kind:'image',src,x,y,w:150,h:150,rotation:0};objects.push(o);selected=o.id;chooseTool('select');inspector();fx('hit');return;}checkpoint();let o={id:uid(),kind:'emoji',text,x,y,w:150,h:150,rotation:0};objects.push(o);selected=o.id;chooseTool('select');inspector();fx('hit');}
function stickerContents(){$('#stickerTabs').innerHTML=Object.keys(STICKERS).map(c=>`<button data-category="${c}" class="${c===category?'selected':''}">${c}</button>`).join('');$('#stickerGrid').innerHTML=STICKERS[category].split(' ').map(s=>`<button class="sticker" data-sticker="${s}" aria-label="Sticker ${s}">${category==='Arcade Originals'?iconArt('sticker',s):s}</button>`).join('');host.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;stickerContents();});host.querySelectorAll('[data-sticker]').forEach(b=>{let start=null,dragged=false;b.onpointerdown=e=>{e.preventDefault();start={x:e.clientX,y:e.clientY};dragged=false;b.setPointerCapture(e.pointerId);};b.onpointermove=e=>{if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>12){dragged=true;$('#stickerDrawer').classList.add('dragging-sticker');}};b.onpointerup=e=>{if(!start)return;let r=canvas.getBoundingClientRect();if(dragged&&e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom)addSticker(b.dataset.sticker,(e.clientX-r.left)/r.width*W,(e.clientY-r.top)/r.height*H);else if(!dragged)addSticker(b.dataset.sticker);start=null;$('#stickerDrawer').classList.remove('dragging-sticker');$('#stickerDrawer').hidden=true;};b.onpointercancel=()=>{start=null;$('#stickerDrawer').classList.remove('dragging-sticker');};});}
$('#stickers').onclick=()=>{$('#stickerDrawer').hidden=false;stickerContents();};$('#closeStickers').onclick=()=>$('#stickerDrawer').hidden=true;
$('#imageUpload').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{if(f.size>25*1024*1024)throw Error('Please choose an image under 25 MB.');let src=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);}),img=await loadImage(src),max=1800;if(Math.max(img.naturalWidth,img.naturalHeight)>max){let scale=max/Math.max(img.naturalWidth,img.naturalHeight),c=document.createElement('canvas');c.width=img.naturalWidth*scale;c.height=img.naturalHeight*scale;c.getContext('2d').drawImage(img,0,0,c.width,c.height);src=c.toDataURL('image/png');await loadImage(src);}checkpoint();let w=Math.min(550,img.naturalWidth),o={id:uid(),kind:'image',src,x:W/2,y:H/2,w,h:w*img.naturalHeight/img.naturalWidth,rotation:0};objects.push(o);selected=o.id;chooseTool('select');inspector();notify('Photo added. Move, resize, rotate, crop, or change its layer.');}catch(e){notify(e.message,'error');}e.target.value='';};
function drawBackground(c){c.fillStyle=background==='blueprint'?'#243d61':background==='space'?'#151b34':background==='cream'?'#fff4dc':'#ffffff';c.fillRect(0,0,W,H);if(background==='dots'){c.fillStyle='#d8d8e5';for(let x=20;x<W;x+=35)for(let y=20;y<H;y+=35){c.beginPath();c.arc(x,y,1.5,0,Math.PI*2);c.fill();}}if(background==='blueprint'){c.strokeStyle='#54739a66';c.lineWidth=1;for(let x=0;x<W;x+=40){c.beginPath();c.moveTo(x,0);c.lineTo(x,H);c.stroke();}for(let y=0;y<H;y+=40){c.beginPath();c.moveTo(0,y);c.lineTo(W,y);c.stroke();}}if(background==='space'){c.fillStyle='#e7ceff';for(let i=0;i<100;i++){let x=(i*193)%W,y=(i*83)%H;c.beginPath();c.arc(x,y,i%3===0?2:1,0,Math.PI*2);c.fill();}}}
function drawObject(c,o){c.save();c.translate(o.x,o.y);c.rotate(o.rotation*Math.PI/180);if(o.kind==='emoji'){c.font=`${Math.min(o.w,o.h)*.85}px 'Segoe UI Emoji','Apple Color Emoji',sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText(o.text,0,0);}else{let img=images.get(o.src);if(img)c.drawImage(img,-o.w/2,-o.h/2,o.w,o.h);else loadImage(o.src).catch(()=>{});}c.restore();}
function composite(c,selection=false){c.clearRect(0,0,W,H);drawBackground(c);c.drawImage(base,0,0);for(let o of objects)drawObject(c,o);if(selection){for(let p of pointers.values())if(['line','circle','rect','triangle','star'].includes(p.tool))shape(c,p);let o=objects.find(o=>o.id===selected);if(o){c.save();c.translate(o.x,o.y);c.rotate(o.rotation*Math.PI/180);c.strokeStyle='#6b5ee8';c.lineWidth=3;c.setLineDash([10,7]);c.strokeRect(-o.w/2-9,-o.h/2-9,o.w+18,o.h+18);c.setLineDash([]);for(let[x,y]of[[-1,-1],[1,-1],[-1,1],[1,1]]){c.fillStyle='#fff';c.strokeStyle='#6b5ee8';c.fillRect(x*(o.w/2+9)-6,y*(o.h/2+9)-6,12,12);c.strokeRect(x*(o.w/2+9)-6,y*(o.h/2+9)-6,12,12);}c.restore();}}}
function render(){if(disposed)return;composite(ctx,true);raf=requestAnimationFrame(render);}
async function saveArt(){nameKeyboard(modal,{title:'Name your masterpiece.',value:name,description:'Saved to '+player().name+'’s Art Gallery. Stickers and photo layers stay editable.',onSave:async title=>{
name=title;const c=document.createElement('canvas');c.width=W;c.height=H;composite(c.getContext('2d'));const thumb=document.createElement('canvas');thumb.width=400;thumb.height=250;thumb.getContext('2d').drawImage(c,0,0,400,250);const pixels=bc.getImageData(0,0,W,H).data;let hasArt=objects.length>0;if(!hasArt)for(let i=3;i<pixels.length;i+=4)if(pixels[i]){hasArt=true;break;}
const copying=owner!==DB.active,nextId=copying?uid():(drawingId||uid()),saveOwner=DB.active;
await mediaPut({id:nextId,type:'art',owner:saveOwner,name,updatedAt:Date.now(),scene:snapshot(),thumb:thumb.toDataURL('image/jpeg',.8),collaborators:collab?[p2].filter(id=>id!==saveOwner):[],toolSettings:structuredClone(settings),qualified:artQualified||hasArt});drawingId=nextId;owner=saveOwner;if(!artQualified&&hasArt){creativeMilestone('art',owner);if(collab)creativeMilestone('art',p2);artQualified=true;}dirty=false;status('Saved · '+name);fx('win');notify('Masterpiece saved to '+player(owner).name+'’s gallery!');toolbars();
}});}

$('#studioSave').onclick=saveArt;$('#studioExport').onclick=()=>modal(`<div class="eyebrow">TAKE YOUR ART WITH YOU</div><h2>Ready for the fridge?</h2><p>Export your finished canvas. Save to your gallery as well if you want to keep editing the layers later.</p><div class="modal-actions"><button class="btn primary" id="exportPNG">PNG · BEST QUALITY</button><button class="btn secondary" id="exportJPG">JPG · SMALLER FILE</button></div>`,d=>{for(let[id,mime,ext]of[['exportPNG','image/png','png'],['exportJPG','image/jpeg','jpg']])d.querySelector('#'+id).onclick=()=>{let c=document.createElement('canvas');c.width=W;c.height=H;composite(c.getContext('2d'));c.toBlob(b=>{download(b,(name.replace(/[^a-z0-9 -]/gi,'')||'My-artwork')+'.'+ext);notify('Artwork exported!');},mime,.92);d.close();};});
async function gallery(){let arts=await mediaAll('art');modal(`<div class="eyebrow">THE ART GALLERY</div><h2>Made with imagination.</h2><label>Artist<select id="galleryOwner"><option value="all">Everyone</option>${DB.profiles.map(p=>`<option value="${p.id}" ${p.id===owner?'selected':''}>${p.avatar} ${esc(p.name)}</option>`).join('')}</select></label><div class="art-gallery" id="galleryItems"></div><button class="btn secondary" id="newCanvas">＋ NEW CANVAS</button>`,d=>{let draw=()=>{let filter=d.querySelector('#galleryOwner').value;d.querySelector('#galleryItems').innerHTML=arts.filter(a=>filter==='all'||a.owner===filter||a.collaborators?.includes(filter)).sort((a,b)=>b.updatedAt-a.updatedAt).map(a=>`<article class="gallery-item"><button data-open-art="${a.id}"><img src="${a.thumb}" alt="${esc(a.name)}"><strong>${esc(a.name)}</strong><small>${esc(player(a.owner)?.name||'Former player')} · ${new Date(a.updatedAt).toLocaleDateString()}</small></button><button class="gallery-rename" data-rename-art="${a.id}" aria-label="Rename ${esc(a.name)}">RENAME</button><button class="gallery-delete" data-delete-art="${a.id}" aria-label="Delete ${esc(a.name)}">✕</button></article>`).join('')||'<div class="empty-state small"><span>🎨</span><p>Your gallery is waiting for its first masterpiece.</p></div>';d.querySelectorAll('[data-open-art]').forEach(b=>b.onclick=async()=>{if(dirty&&!await ask('Open this artwork?','Save your current edits first if you want to keep them.'))return;let a=await mediaGet(b.dataset.openArt);if(!a)return;await applySnapshot(a.scene);drawingId=a.id;owner=a.owner;name=a.name;settings=restoreDrawingSettings(a.toolSettings);artQualified=a.qualified!==false;p2=a.collaborators?.find(id=>player(id))||DB.profiles.find(p=>p.id!==owner)?.id;collab=!!a.collaborators?.length&&!!p2;$('#collab').checked=collab;$('#studioP2').innerHTML=DB.profiles.filter(p=>p.id!==owner).map(p=>`<option value="${p.id}" ${p.id===p2?'selected':''}>${p.avatar} ${esc(p.name)}</option>`).join('');$('#studioP2').hidden=!collab;$('#collabLabel').hidden=!collab;toolbars();history=[];future=[];updateHistory();dirty=false;$('#studioOwner').textContent=(player(owner)?.avatar||'🎨')+' '+(player(owner)?.name||'Former player')+'’s canvas';d.close();status('Editing · '+name);});d.querySelectorAll('[data-rename-art]').forEach(b=>b.onclick=()=>{const a=arts.find(a=>a.id===b.dataset.renameArt);nameKeyboard(modal,{title:'Rename your artwork',value:a.name,onSave:async title=>{a.name=title;a.updatedAt=Date.now();await mediaPut(a);if(drawingId===a.id)name=title;notify('Artwork renamed.');}});});d.querySelectorAll('[data-delete-art]').forEach(b=>b.onclick=async()=>{if(await ask('Delete this artwork?','This removes the saved drawing from the gallery. Export it first if you want a copy.')){await mediaDelete(b.dataset.deleteArt);arts=arts.filter(a=>a.id!==b.dataset.deleteArt);draw();}});};d.querySelector('#galleryOwner').onchange=draw;d.querySelector('#newCanvas').onclick=async()=>{if(dirty&&!await ask('Start a new canvas?','Save your current edits first if you want to keep them.'))return;bc.clearRect(0,0,W,H);objects=[];history=[];future=[];drawingId=null;artQualified=false;owner=DB.active;settings=newDrawingSettings();toolbars();name='My masterpiece';dirty=false;selected=null;inspector();updateHistory();d.close();};draw();});}
$('#studioGallery').onclick=()=>gallery().catch(e=>notify('Gallery could not be opened: '+e.message,'error'));
function visibility(){if(document.hidden)pointers.clear();}document.addEventListener('visibilitychange',visibility);const resizeCanvas=()=>{let r=$('#artStage').getBoundingClientRect(),pad=innerWidth<650?20:60,w=Math.max(100,Math.min(r.width-pad,(r.height-pad)*W/H)),frame=$('.canvas-shadow');frame.style.width=w+'px';frame.style.height=(w*H/W)+'px';};const observer=new ResizeObserver(resizeCanvas);observer.observe($('#artStage'));resizeCanvas();toolbars();updateHistory();render();
return()=>{disposed=true;observer.disconnect();cancelAnimationFrame(raf);pointers.clear();images.clear();document.removeEventListener('visibilitychange',visibility);};
}
function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
